def icon(name: str, cls: str = "icon") -> str:
    return f'<svg class="{cls}" aria-hidden="true"><use href="#icon-{escape(name)}"></use></svg>'


def badge(text: str, kind: str = "") -> str:
    cls = f"badge badge-{kind}" if kind else "badge"
    return f'<span class="{cls}">{escape(text)}</span>'


def button(text: str, href: str | None = None, kind: str = "", icon_name: str | None = None, small: bool = False, toast: str | None = None) -> str:
    classes = ["btn"]
    if kind:
        classes.append(f"btn-{kind}")
    if small:
        classes.append("btn-sm")
    contents = (icon(icon_name) if icon_name else "") + f"<span>{escape(text)}</span>"
    if href:
        return f'<a class="{" ".join(classes)}" href="{escape(href)}">{contents}</a>'
    toast_attr = f' data-toast="{escape(toast)}"' if toast else ""
    return f'<button class="{" ".join(classes)}" type="button"{toast_attr}>{contents}</button>'


def nav_markup(current: str) -> str:
    items = []
    for href, key, icon_name, label in NAV:
        active = " active" if key == current else ""
        current_attr = ' aria-current="page"' if key == current else ""
        items.append(f'<a class="nav-item{active}" href="{href}"{current_attr} title="{label}">{icon(icon_name)}<span>{label}</span></a>')
    return "\n".join(items)


def support_nav_markup(current: str) -> str:
    items = []
    for href, key, icon_name, label in SUPPORT_LINKS:
        active = " active" if key == current else ""
        current_attr = ' aria-current="page"' if key == current else ""
        items.append(f'<a class="nav-item{active}" href="{href}"{current_attr} title="{label}">{icon(icon_name)}<span>{label}</span></a>')
    return "\n".join(items)


