def sparkline(points: str = "0,36 14,32 28,34 42,24 56,27 70,17 84,20 100,8") -> str:
    return f'''<svg class="sparkline" viewBox="0 0 100 42" preserveAspectRatio="none" aria-label="Trend chart"><path class="area" d="M{points.replace(' ', ' L')} L100,42 L0,42 Z"/><polyline class="line" points="{points}"/></svg>'''


def metric(label: str, value: str, unit: str, delta: str, icon_name: str = "database", delta_class: str = "") -> str:
    return f'''<section class="card metric-card"><div><div class="metric-top"><span class="metric-label">{escape(label)}</span><span class="text-brand">{icon(icon_name)}</span></div><div class="metric-value">{escape(value)}</div><div class="metric-unit">{escape(unit)}</div></div><div class="metric-delta {escape(delta_class)}">{escape(delta)}</div></section>'''


def write(name: str, html: str) -> None:
    (ROOT / name).write_text(html, encoding="utf-8")

