def page_intent_contract() -> str:
    actions = button("Compare versions", kind="subtle", icon_name="history") + button("Save revision", kind="primary", icon_name="check", toast="Intent and workflow revision saved as a new version.")
    use_cases = [
        ("theory-synthesis","Theory synthesis","Integrate constructs, mechanisms, definitions, theory use, levels, and boundaries.","Search → Evidence → Theory Map → Claim Graph → Opportunities → Synthesis"),
        ("systematic-review","Systematic / scoping review","Build a reproducible corpus with auditable screening, extraction, and reporting.","Sources → Search → Ingestion → Screening → Evidence → Synthesis → Audit"),
        ("rapid-orientation","Rapid field orientation","Learn vocabulary, seminal work, schools, and contested claims without pretending comprehensiveness.","Search → Corpus map → Reading → Theory/claims → Orientation synthesis"),
        ("living-review","Living review","Update an existing synthesis through differential retrieval and impact-aware recalculation.","Monitor → Differential search → Screening → Evidence → Updated synthesis"),
        ("hermeneutic-inquiry","Hermeneutic inquiry","Iterate among searching, reading, memoing, and reframing as understanding evolves.","Search ↔ Read ↔ Notebook ↔ Reframe → Interpretive synthesis"),
        ("critical-problematization","Critical problematization","Surface assumptions, authority, dependency, stakeholders, silences, and excluded alternatives.","Search → Read/memo → Evidence → Critical Lens → Claims → Problematization dossier"),
        ("technical-landscape","Technical landscape / benchmark audit","Compare models, data, baselines, controls, compute, ablations, and external validity.","Search → Corpus → Screening → Evidence matrix → Comparisons → Opportunities → Synthesis"),
        ("novelty-audit","Novelty & research-opportunity audit","Challenge a proposed contribution against nearest prior work and alternative framings.","Intent → Search → Evidence → Opportunity → Novelty challenge → Dossier"),
    ]
    cards = []
    for key, title, desc, sequence in use_cases:
        selected = key == 'theory-synthesis'
