def page_synthesis_studio() -> str:
    actions = button("Citation audit", icon_name="shield", toast="Citation audit opened.") + button("Export", kind="primary", icon_name="download", toast="Export options opened.")
    content = dedent(f"""
      <section class="grid grid-three-pane">
        <aside class="card card-lg"><div class="card-header"><div><h2 class="card-title">Synthesis outline</h2><div class="card-subtitle">Version 4 · evidence packet 214</div></div>{badge('Draft','brand')}</div><div class="list"><div class="list-item" style="background:var(--brand-50);margin-inline:-.5rem;padding-inline:.5rem"><span class="list-leading">1</span><span class="list-content"><span class="list-title">Construct fragmentation</span><span class="list-meta">42 claims · 78 evidence records</span></span></div><div class="list-item"><span class="list-leading">2</span><span class="list-content"><span class="list-title">Mechanisms of augmentation</span><span class="list-meta">36 claims · 64 evidence records</span></span></div><div class="list-item"><span class="list-leading">3</span><span class="list-content"><span class="list-title">Measurement sensitivity</span><span class="list-meta">29 claims · 52 evidence records</span></span></div><div class="list-item"><span class="list-leading">4</span><span class="list-content"><span class="list-title">Boundary conditions</span><span class="list-meta">31 claims · 61 evidence records</span></span></div><div class="list-item"><span class="list-leading">5</span><span class="list-content"><span class="list-title">Research opportunities</span><span class="list-meta">7 accepted dossiers</span></span></div></div><button class="btn" style="width:100%;margin-top:1rem" data-toast="Outline item added.">Add section</button></aside>

        <article class="card card-lg"><div class="card-header"><div><div class="tiny muted">Section 1 · Construct fragmentation</div><h2 class="section-title" style="font-family:var(--font-serif)">Creative performance is not one stable outcome</h2></div><div class="chip-row">{badge('14 citations','success')} {badge('2 disagreements','warning')}</div></div><p class="small" style="font-size:var(--text-lg);line-height:1.75">Across the literature, “creative performance” is operationalized through at least four outcome families: ideational fluency, semantic or categorical diversity, evaluator-rated originality, and process-level revision quality. These measures are correlated but not interchangeable. Studies emphasizing search-space expansion more consistently report benefits from generative AI, whereas evaluator-rated originality is more sensitive to domain expertise, task constraints, and the composition of the evaluator panel <a class="text-brand" href="document-reader.html">[Alvarez et al., 2026]</a> <a class="text-brand" href="document-reader.html">[Chen et al., 2025]</a>.</p><p class="small" style="font-size:var(--text-lg);line-height:1.75">This variation is theoretically consequential. Treating all outcome families as equivalent can make the same evidence appear supportive, null, or contradictory. The literature therefore supports a measurement-contingent account rather than an undifferentiated augmentation claim.</p><div class="notice warning"><span>{icon('warning')}</span><div><div class="notice-title">Disagreement preserved</div><div class="notice-text">Five studies report no expert-rated originality gain despite higher semantic diversity. The draft does not collapse this into consensus.</div></div></div><div class="divider"></div><div class="toolbar"><button class="btn btn-sm">Insert accepted claim</button><button class="btn btn-sm">Insert table</button><button class="btn btn-sm">Insert disagreement</button><button class="btn btn-sm">Add memo</button><span class="toolbar-spacer"></span><span class="tiny muted">Autosaved 1 minute ago</span></div></article>

        <aside class="card card-lg"><div class="card-header"><div><h2 class="card-title">Evidence packet</h2><div class="card-subtitle">Only accepted evidence and decisions are available for synthesis.</div></div>{badge('214','brand')}</div><div class="tabs" data-tab-group><button class="tab active" data-tab="claims">Claims</button><button class="tab" data-tab="citations">Citations</button><button class="tab" data-tab="audit">Audit</button></div><div class="list"><a class="list-item" href="claim-graph.html"><span class="list-content"><span class="list-title">AI expands ideational variety</span><span class="list-meta">17 evidence records · qualified</span></span>{badge('Accepted','success')}</a><a class="list-item" href="claim-graph.html"><span class="list-content"><span class="list-title">Originality gains depend on expertise</span><span class="list-meta">9 evidence records · moderate confidence</span></span>{badge('Accepted','success')}</a><a class="list-item" href="claim-graph.html"><span class="list-content"><span class="list-title">Evaluation method explains divergence</span><span class="list-meta">12 evidence records · 2 disputes</span></span>{badge('Disputed','danger')}</a></div><div class="divider"></div><h3 class="card-title">Citation audit</h3><div class="list"><div class="list-item"><span class="list-content"><span class="list-title">Support correctness</span><span class="list-meta">14 of 14 cited claims resolve to supporting passages</span></span>{badge('Pass','success')}</div><div class="list-item"><span class="list-content"><span class="list-title">Citation completeness</span><span class="list-meta">Two sentences may need additional support</span></span>{badge('Review','warning')}</div><div class="list-item"><span class="list-content"><span class="list-title">Rights check</span><span class="list-meta">All exports contain only permitted derived content</span></span>{badge('Pass','success')}</div></div></aside>
      </section>
      <section class="grid grid-3 section"><article class="card card-lg"><div class="card-header"><h2 class="card-title">PRISMA-style flow</h2>{badge('Current','success')}</div><div class="flow-diagram"><div class="flow-node">18,742<br><span class="tiny muted">identified</span></div><div class="flow-node">11,399<br><span class="tiny muted">screened</span></div><div class="flow-node">4,105<br><span class="tiny muted">included</span></div><div class="flow-node">1,204<br><span class="tiny muted">deep coded</span></div></div></article><article class="card card-lg"><div class="card-header"><h2 class="card-title">Export package</h2>{icon('download')}</div><div class="chip-row"><span class="chip">DOCX report</span><span class="chip">Markdown</span><span class="chip">CSV evidence</span><span class="chip">JSON-LD graph</span><span class="chip">Search manifest</span><span class="chip">AI disclosure</span></div><button class="btn btn-primary" style="width:100%;margin-top:1rem" data-toast="Reproducibility package queued.">Build reproducibility package</button></article><article class="card card-lg"><div class="card-header"><h2 class="card-title">AI-use disclosure</h2>{badge('Editable','info')}</div><p class="small muted">Search expansion, extraction, verification triage, graph candidates, and novelty challenge were AI-assisted. Inclusion, interpretation, adjudication, and final contribution language were researcher-approved.</p><button class="btn" style="width:100%" data-toast="Disclosure editor opened.">Edit disclosure</button></article></section>
    """)
    return shell("synthesis-studio", "Synthesis Studio", "Assemble accepted claims and evidence into reviewer-defensible narratives, tables, citation audits, disclosures, and reproducibility packages.", content, actions, "Evidence-grounded synthesis")



