    use_cases = [
        ("Rapid field orientation","Learn vocabulary, seminal work, schools, and debates.","7 stages","Field map, reading path, contested claims"),
        ("Systematic / scoping review","Build and report a reproducible evidence corpus.","10 stages","Corpus, evidence table, synthesis, audit bundle"),
        ("Living review","Update an existing review as evidence changes.","8 cyclical stages","Change report, updated synthesis, alerts"),
        ("Theory synthesis","Integrate constructs, mechanisms, theories, and boundaries.","10 stages","Theory architecture and integration opportunities"),
        ("Hermeneutic inquiry","Cycle among searching, reading, memoing, and reframing.","7 cyclical stages","Interpretive map and rationale trail"),
        ("Critical problematization","Challenge assumptions, authority, exclusions, and alternatives.","10 stages","Problematization dossier"),
        ("Technical landscape / benchmark audit","Compare methods, data, baselines, compute, and evaluation.","9 stages","Benchmark map and design opportunities"),
        ("Novelty & opportunity audit","Test a contribution against nearest prior work.","7 stages","Bounded novelty dossier"),
        ("Empirical study design","Turn evidence and opportunity into a feasible empirical protocol.","9 stages","Study-design dossier and protocol skeleton"),
        ("Empirical study to article","Move from literature and design through results to a full article.","14 stages","Protocol, results, article, reviews, revision"),
        ("Empirical results to article","Begin from technical reports and completed empirical work.","11 stages","Verified results and full empirical article"),
        ("Theory article development","Develop an integrated theoretical contribution into a paper.","15 stages","Theory manuscript and review package"),
        ("Critical article development","Develop critical problematization into a full paper.","15 stages","Critical manuscript and review package"),
        ("Manuscript review & revision","Challenge, revise, and prepare a response for a draft.","8 cyclical stages","Reviews, revised manuscript, response"),
    ]
    cards=''.join([f'<article class="card card-lg"><div class="card-header"><h3 class="card-title">{title}</h3>{badge(stages,"brand")}</div><p class="small muted">{desc}</p><div class="tiny strong">Primary output</div><div class="small">{output}</div></article>' for title,desc,stages,output in use_cases])
    content = dedent(f"""
      <section class="grid grid-main-aside"><div class="grid"><article class="card card-lg"><div class="card-header"><div><h2 class="card-title">Getting started</h2><div class="card-subtitle">The application begins with the objective, not with a menu of disconnected tools.</div></div>{badge('4 of 6 complete','brand')}</div><div class="list"><a class="list-item" href="new-project.html"><span class="list-leading text-success">{icon('check')}</span><span class="list-content"><span class="list-title">Choose a primary use case</span><span class="list-meta">Defines the ordered workflow and output expectations</span></span></a><a class="list-item" href="intent-contract.html"><span class="list-leading text-success">{icon('check')}</span><span class="list-content"><span class="list-title">Confirm the Research Intent Contract</span><span class="list-meta">Scope, evidence, authority, article type, novelty, and stopping logic</span></span></a><a class="list-item" href="source-manager.html"><span class="list-leading">{icon('database')}</span><span class="list-content"><span class="list-title">Configure lawful and private sources</span><span class="list-meta">Literature, technical reports, manuscript drafts, and local files remain rights-aware</span></span></a><a class="list-item" href="index.html"><span class="list-leading">{icon('arrow-right')}</span><span class="list-content"><span class="list-title">Follow the highlighted next step</span><span class="list-meta">Previous, next, progress, rationale, quality gate, and output appear on every workflow page</span></span></a></div></article><article class="card card-lg" id="workflows"><div class="card-header"><div><h2 class="card-title">Use-case catalog</h2><div class="card-subtitle">Each use case has a distinct sequence, defaults, checkpoints, and output—not just a differently named project.</div></div><a class="card-link" href="new-project.html">Start a project →</a></div><div class="grid grid-2">{cards}</div></article></div><aside class="grid" style="align-content:start"><article class="card card-lg"><div class="card-header"><h2 class="card-title">Navigation model</h2>{icon('layers')}</div><div class="list"><div class="list-item"><span class="list-leading">1</span><span class="list-content"><span class="list-title">Guided workflow</span><span class="list-meta">Ordered, numbered, and visually dominant</span></span></div><div class="list-item"><span class="list-leading">2</span><span class="list-content"><span class="list-title">Context bar</span><span class="list-meta">Explains why the current tool matters and what comes next</span></span></div><div class="list-item"><span class="list-leading">3</span><span class="list-content"><span class="list-title">All tools</span><span class="list-meta">Always available without obscuring the primary path</span></span></div></div></article><article class="card card-lg"><div class="card-header"><h2 class="card-title">Research-production safeguards</h2>{badge('Human gates','warning')}</div><div class="list"><div class="list-item"><span class="list-leading">{icon('flask')}</span><span class="list-content"><span class="list-title">Study design is a proposal</span><span class="list-meta">Ethics, feasibility, and protocol decisions require researcher approval</span></span></div><div class="list-item"><span class="list-leading">{icon('upload')}</span><span class="list-content"><span class="list-title">Results are never invented</span><span class="list-meta">Only reported or reproducibly calculated values enter result records</span></span></div><div class="list-item"><span class="list-leading">{icon('review')}</span><span class="list-content"><span class="list-title">Reviewer simulation is advisory</span><span class="list-meta">No acceptance probability and no named-reviewer impersonation</span></span></div></div></article><article class="card card-lg"><div class="card-header"><h2 class="card-title">Offline help & diagnostics</h2>{badge('Local','success')}</div><div class="list"><div class="list-item"><span class="list-leading">{icon('document')}</span><span class="list-content"><span class="list-title">Contextual guides</span><span class="list-meta">Definitions, task purpose, and evidence standards</span></span></div><div class="list-item"><span class="list-leading">{icon('tasks')}</span><span class="list-content"><span class="list-title">Keyboard reference</span><span class="list-meta">Navigation, table, source, manuscript, and review shortcuts</span></span></div><div class="list-item"><span class="list-leading">{icon('shield')}</span><span class="list-content"><span class="list-title">Redacted support bundle</span><span class="list-meta">No papers, reports, drafts, prompts, memos, or unpublished ideas by default</span></span></div></div></article></aside></section>
    """)
