def page_style_guide() -> str:
    actions = button("Page index", "prototype-index.html", icon_name="grid") + button("Toggle theme", kind="primary", icon_name="moon", toast="Use the moon/sun control in the application top bar to compare themes.")
    light_tokens = [
        ("Canvas", "#F5F7FB", "--canvas"), ("Surface 1", "#FFFFFF", "--surface-1"), ("Surface 2", "#F8FAFD", "--surface-2"),
        ("Border", "#D9E2EE", "--border-subtle"), ("Text strong", "#10233D", "--text-strong"), ("Text muted", "#5B7089", "--text-muted"),
        ("Brand 600", "#2563EB", "--brand-600"), ("Brand 800", "#1E40AF", "--brand-800"),
    ]
    dark_tokens = [
        ("Canvas", "#061527", "--canvas"), ("Surface 1", "#0B1F37", "--surface-1"), ("Surface 2", "#102740", "--surface-2"),
        ("Border", "#263F5D", "--border-subtle"), ("Text strong", "#F4F8FF", "--text-strong"), ("Text muted", "#9DB0C6", "--text-muted"),
        ("Brand 500", "#5B91FF", "--brand-500"), ("Brand 700", "#3D70DC", "--brand-700"),
    ]
    def swatches(items):
        return ''.join([f'<div class="token-swatch"><div class="token-color" style="--swatch:{hexv}"></div><div class="token-meta"><div class="token-name">{name}</div><div class="token-value">{token}<br>{hexv}</div></div></div>' for name,hexv,token in items])
    content = dedent(f"""
      <div class="notice"><span>{icon('info')}</span><div><div class="notice-title">Approved experience reference: Academic Minimal 1.3</div><div class="notice-text">Crisp white and cool-gray light surfaces, deep navy dark surfaces, restrained royal-blue interaction accents, serif display headings, compact sans-serif workbench text, and minimal decorative effects. Tokens, semantics, page contracts, and required interaction behavior are normative; names, counts, vendors, sample prose, and inactive mock actions are illustrative.</div></div></div>

      <section class="section" id="principles"><div class="section-header"><div><h2 class="section-title">1. Visual principles</h2><div class="section-description">The interface should communicate rigor before novelty and depth before decoration.</div></div></div><div class="grid grid-4"><article class="card card-lg"><h3 class="card-title">Evidence before prose</h3><p class="small muted">Primary actions expose sources, passages, status, and uncertainty. Generated prose is downstream.</p></article><article class="card card-lg"><h3 class="card-title">Quiet structure</h3><p class="small muted">Use borders, spacing, alignment, and typographic hierarchy before shadows or color.</p></article><article class="card card-lg"><h3 class="card-title">Blue means interaction</h3><p class="small muted">Royal blue identifies selection, active navigation, links, focus, and primary actions—not all data.</p></article><article class="card card-lg"><h3 class="card-title">State colors have fixed meaning</h3><p class="small muted">Semantic and evidence-state colors must not be reassigned by page or chart.</p></article></div></section>

      <section class="section" id="color"><div class="section-header"><div><h2 class="section-title">2. Color system</h2><div class="section-description">Theme tokens change values; component names and semantic meaning remain stable.</div></div></div><div class="grid grid-2"><article class="card card-lg"><div class="card-header"><h3 class="card-title">Light theme</h3>{badge('Default','brand')}</div><div class="token-grid">{swatches(light_tokens)}</div></article><article class="card card-lg"><div class="card-header"><h3 class="card-title">Dark theme</h3>{badge('Deep navy','info')}</div><div class="token-grid">{swatches(dark_tokens)}</div></article></div><article class="card card-lg section"><div class="card-header"><h3 class="card-title">Semantic and evidence states</h3><span class="tiny muted">Use text + icon + label; never color alone.</span></div><div class="chip-row">{badge('Success / verified','success')} {badge('Warning / adjudicated','warning')} {badge('Danger / disputed','danger')} {badge('Information / extracted','info')} {badge('Inferred / critical candidate','violet')} <span class="badge" style="color:var(--state-observed)">Observed</span> <span class="badge" style="color:var(--state-stale)">Stale</span></div></article></section>

      <section class="section" id="typography"><div class="section-header"><div><h2 class="section-title">3. Typography</h2><div class="section-description">Use serif selectively for page identity, research statements, and long-form synthesis—not for dense controls or tables.</div></div></div><div class="grid grid-2"><article class="card card-lg"><div class="eyebrow">Project workspace</div><h1 class="page-title">Generative AI and Creative Cognition</h1><p class="page-subtitle">32 px / 40 px, Source Serif 4 or system serif fallback, weight 650.</p><h2 class="section-title" style="margin-top:1.5rem">Section heading</h2><p class="small muted">18 px / 26 px, sans-serif, weight 760.</p><h3 class="card-title" style="margin-top:1.25rem">Card heading</h3><p class="tiny muted">13 px / 18 px, sans-serif, weight 760.</p></article><article class="card card-lg"><div class="table-wrap"><table><thead><tr><th>Role</th><th>Size / line</th><th>Family</th><th>Use</th></tr></thead><tbody><tr><td>Display</td><td>40 / 48</td><td>Serif</td><td>Rare hero or dossier title</td></tr><tr><td>Page title</td><td>32 / 40</td><td>Serif</td><td>One per page</td></tr><tr><td>Section</td><td>18 / 26</td><td>Sans</td><td>Primary content sections</td></tr><tr><td>Body</td><td>14 / 21</td><td>Sans</td><td>Default UI and explanation</td></tr><tr><td>Small</td><td>12 / 18</td><td>Sans</td><td>Tables, metadata, helper text</td></tr><tr><td>Label</td><td>11 / 16</td><td>Sans</td><td>Uppercase eyebrows and column labels</td></tr><tr><td>Code</td><td>12 / 20</td><td>Mono</td><td>IDs, queries, manifests</td></tr></tbody></table></div></article></div></section>

      <section class="section" id="layout"><div class="section-header"><div><h2 class="section-title">4. Layout, spacing, and size</h2><div class="section-description">A 4 px base unit supports dense research work without visual crowding.</div></div></div><div class="grid grid-3"><article class="card card-lg"><h3 class="card-title">Application frame</h3><dl class="key-value"><dt>Top bar</dt><dd>64 px</dd><dt>Sidebar</dt><dd>240 px expanded; 72 px collapsed</dd><dt>Content max</dt><dd>1680 px</dd><dt>Page padding</dt><dd>28 px desktop</dd><dt>Grid gap</dt><dd>16 px</dd></dl></article><article class="card card-lg"><h3 class="card-title">Components</h3><dl class="key-value"><dt>Card radius</dt><dd>10 px</dd><dt>Card padding</dt><dd>16 px; 20 px large</dd><dt>Controls</dt><dd>32 / 40 / 44 px</dd><dt>Table rows</dt><dd>38 px compact; 44 px default</dd><dt>Drawer</dt><dd>400 px</dd></dl></article><article class="card card-lg"><h3 class="card-title">Spacing scale</h3><div class="chip-row"><span class="chip">4</span><span class="chip">8</span><span class="chip">12</span><span class="chip">16</span><span class="chip">20</span><span class="chip">24</span><span class="chip">32</span><span class="chip">40</span><span class="chip">48</span><span class="chip">64 px</span></div><p class="tiny muted" style="margin-top:1rem">Prefer 16 px card gaps and 24–32 px between major page sections.</p></article></div></section>

      <section class="section" id="components"><div class="section-header"><div><h2 class="section-title">5. Core components</h2><div class="section-description">Components use the same anatomy and state language across every workspace.</div></div></div><div class="grid grid-2"><article class="card card-lg"><h3 class="card-title">Buttons and controls</h3><div class="toolbar" style="margin-top:1rem">{button('Primary action',kind='primary')}{button('Secondary action')}{button('Subtle',kind='subtle')}{button('Danger',kind='danger')}{button('Small',small=True)}</div><div class="grid grid-2"><div class="field"><label class="field-label">Text input</label><input class="input" value="Evidence-grounded query"></div><div class="field"><label class="field-label">Select</label><select class="select"><option>Theory synthesis</option></select></div></div><div class="tabs" style="margin-top:1.25rem"><button class="tab active">Active tab</button><button class="tab">Second tab</button><button class="tab">Third tab</button></div></article><article class="card card-lg"><h3 class="card-title">Cards, list rows, and progress</h3><div class="card" style="margin-top:1rem"><div class="card-header"><div><h4 class="card-title">Evidence verification</h4><div class="card-subtitle">31 records remain</div></div>{badge('In progress','brand')}</div><div class="progress" style="--value:68%"><span></span></div></div><div class="list"><div class="list-item"><span class="list-leading">{icon('document')}</span><span class="list-content"><span class="list-title">Source passage linked</span><span class="list-meta">p. 13 · Results · paragraph 2</span></span>{badge('Verified','success')}</div><div class="list-item"><span class="list-leading">{icon('warning')}</span><span class="list-content"><span class="list-title">Interpretation disputed</span><span class="list-meta">Alternative reading retained</span></span>{badge('Review','danger')}</div></div></article></div></section>

      <section class="section" id="charts"><div class="section-header"><div><h2 class="section-title">6. Data visualization</h2><div class="section-description">Charts explain evidence structure; they are not ornamental dashboard decoration.</div></div></div><div class="grid grid-3"><article class="card card-lg"><h3 class="card-title">Chart palette</h3><div class="token-grid">{swatches([('Blue','#2F6DEB','--chart-1'),('Cyan','#0891B2','--chart-2'),('Violet','#7C3AED','--chart-3'),('Green','#16A34A','--chart-4'),('Amber','#D97706','--chart-5'),('Magenta','#DB2777','--chart-6')])}</div></article><article class="card card-lg"><h3 class="card-title">Mini trend</h3>{sparkline()}<p class="tiny muted">Use for a trend summary only; provide exact values elsewhere.</p><div class="bar-chart"><span style="--h:26%"></span><span style="--h:46%"></span><span style="--h:38%"></span><span style="--h:72%"></span><span style="--h:61%"></span><span style="--h:86%"></span></div></article><article class="card card-lg"><h3 class="card-title">Composition</h3><div class="donut" style="--p:68%;--donut-color:var(--chart-1);width:7rem;margin:1rem auto"><span>68%</span></div><div class="legend"><div class="legend-item"><span class="legend-swatch" style="--swatch:var(--chart-1)"></span>Included</div><div class="legend-item"><span class="legend-swatch" style="--swatch:var(--chart-5)"></span>Screening</div><div class="legend-item"><span class="legend-swatch" style="--swatch:var(--chart-3)"></span>Excluded</div></div></article></div></section>

      <section class="section" id="behavior"><div class="section-header"><div><h2 class="section-title">7. Behavior and accessibility</h2><div class="section-description">Desktop-first does not mean mouse-only or visually dependent.</div></div></div><div class="grid grid-3"><article class="card card-lg"><h3 class="card-title">Keyboard</h3><p class="small muted">Visible focus ring; logical tab order; workspace landmarks; keyboard-accessible graph alternatives; Escape closes transient surfaces.</p></article><article class="card card-lg"><h3 class="card-title">Motion</h3><p class="small muted">120–180 ms transitions. No essential meaning in animation. Respect reduced-motion settings and disable large graph transitions.</p></article><article class="card card-lg"><h3 class="card-title">Contrast</h3><p class="small muted">Target WCAG AA for text and controls. Use color with labels, icons, shapes, patterns, or table columns.</p></article></div></section>

      <section class="section" id="page-archetypes"><div class="section-header"><div><h2 class="section-title">8. Page archetypes</h2><div class="section-description">Choose the archetype based on the primary scholarly action rather than forcing every page into a dashboard.</div></div></div><div class="table-wrap"><table><thead><tr><th>Archetype</th><th>Pages</th><th>Primary layout</th><th>Interaction priority</th></tr></thead><tbody><tr><td>Overview dashboard</td><td>Project Home, Living Monitor</td><td>KPI strip + 2–3 column cards</td><td>Orient and route decisions</td></tr><tr><td>Workbench</td><td>Search, Screening, Ingestion, Synthesis</td><td>Three pane or sidebar + main</td><td>Complete focused scholarly work</td></tr><tr><td>Matrix / data grid</td><td>Evidence Matrix, Audit, Parsing Quality</td><td>Table + detail drawer</td><td>Compare and inspect provenance</td></tr><tr><td>Visual map</td><td>Corpus, Claim Graph, Theory Map, Radar</td><td>Canvas + inspector</td><td>Move from pattern to source</td></tr><tr><td>Reader</td><td>Document Reader</td><td>Outline + page + inspector</td><td>Source-first evidence work</td></tr><tr><td>Governance form</td><td>Intent, Schema, Settings, Models</td><td>Form sections + impact aside</td><td>Make consequential policy explicit</td></tr><tr><td>Guided support</td><td>Help & Onboarding</td><td>Checklist + guides + diagnostics</td><td>Teach without hiding authority</td></tr><tr><td>Study design</td><td>Study Design Studio</td><td>Stage rail + design workspace + validity inspector</td><td>Compare and formalize empirical alternatives</td></tr><tr><td>Article architecture</td><td>Manuscript Blueprint</td><td>Outline + claim plan + venue/evidence inspector</td><td>Plan before drafting</td></tr><tr><td>Research production</td><td>Technical Reports, Manuscript Studio</td><td>Library/outline + workspace + evidence inspector</td><td>Integrate verified results and draft supported prose</td></tr><tr><td>Review and revision</td><td>Reviewer Simulation, Revision & Response</td><td>Review index + synthesis/diff + lineage inspector</td><td>Challenge independently, adjudicate, and revise</td></tr></tbody></table></div></section>

      <section class="section" id="governance"><div class="section-header"><div><h2 class="section-title">9. Experience-reference governance</h2><div class="section-description">Intentional user-facing changes are designed and approved here before implementation.</div></div></div><div class="grid grid-3"><article class="card card-lg"><h3 class="card-title">Normative</h3><p class="small muted">Design tokens, semantic state meanings, page routes, required regions, navigation, interaction and accessibility behavior, and light/dark parity.</p></article><article class="card card-lg"><h3 class="card-title">Illustrative</h3><p class="small muted">Mock names, counts, studies, provider examples, dates, prose, charts, and nonfunctional actions. They do not authorize backend scope.</p></article><article class="card card-lg"><h3 class="card-title">Design-first change order</h3><p class="small muted">Update the style guide and affected HTML page contracts, regenerate and validate the reference, obtain human approval, then claim the implementation task and attach conformance evidence.</p></article></div><div class="notice" style="margin-top:1rem"><span>{icon('shield')}</span><div><div class="notice-title">Reference viewport and responsive obligation</div><div class="notice-text">Baseline visual captures use 1440 × 900 in light and dark themes. The product must remain usable at 1280 × 720 and at supported desktop scaling from 100% through 200% on Windows x64, macOS Apple Silicon, Linux x64, and Linux ARM64; responsive collapse must preserve all functions and keyboard access.</div></div></div></section>
    """)
    content += dedent(f"""
      <section class="section" id="workflow-navigation"><div class="section-header"><div><h2 class="section-title">10. Guided workflow and adaptive navigation</h2><div class="section-description">The interface is organized around scholarly objectives rather than presenting every workspace as an equal disconnected tool.</div></div></div><div class="grid grid-3"><article class="card card-lg"><h3 class="card-title">Primary use case</h3><p class="small muted">Selected during project creation and governed by the Research Intent Contract. It controls ordered steps, defaults, checkpoints, recommended outputs, and next-step rationale.</p></article><article class="card card-lg"><h3 class="card-title">Guided workflow</h3><p class="small muted">Numbered steps use 28 px markers, 40 px minimum rows, brand blue for current, success green for complete, neutral slate for upcoming, violet outline for optional, and warning amber only for attention.</p></article><article class="card card-lg"><h3 class="card-title">All tools remain available</h3><p class="small muted">A secondary “All tools” disclosure preserves expert access. When a user opens a supporting tool, the context bar explains that it is outside the primary sequence and offers a return to the current step.</p></article></div><div class="workflow-context example"><div class="workflow-context-main"><span class="badge badge-brand">Theory synthesis</span><strong>Step 6 of 10 · Evidence Matrix</strong><span class="small muted">Verify comparable evidence before building theory and claim relations.</span></div><div class="workflow-context-actions"><button class="btn">← Previous</button><button class="btn btn-primary">Next: Theory Map →</button></div></div><div class="workflow-map" style="margin-top:1rem"><div class="workflow-map-step complete"><span>1</span><small>Intent</small></div><div class="workflow-map-step complete"><span>2</span><small>Search</small></div><div class="workflow-map-step complete"><span>3</span><small>Corpus</small></div><div class="workflow-map-step current"><span>4</span><small>Evidence</small></div><div class="workflow-map-step"><span>5</span><small>Theory</small></div><div class="workflow-map-step"><span>6</span><small>Synthesis</small></div></div><div class="notice" style="margin-top:1rem"><span>{icon('info')}</span><div><div class="notice-title">Workflow rules</div><div class="notice-text">Project creation must offer all fourteen approved use cases. Changing use case is versioned and previews effects. Linear workflows may include optional or cyclical steps, but the user always sees current position, rationale, previous/next actions, incomplete gates, and the full tool inventory.</div></div></div></section>
    """)
    return shell("style-guide", "Academic Minimal Style Guide", "Implementation specification for the preferred Research Observatory visual system across light and dark themes.", content, actions, "Design system")


def page_prototype_index() -> str:
    actions = button("Open style guide", "style-guide.html", kind="primary", icon_name="layers") + button("Create project", "new-project.html", icon_name="plus")
    groups = [
        ("Start with the objective", [("projects.html","Projects","Open projects and see their primary use case and workflow position."),("new-project.html","New Project","Choose one of fourteen objective-specific workflows before configuring tools."),("intent-contract.html","Research Intent Contract","Version use case, scope, evidence, authority, article type, novelty, and stopping logic."),("index.html","Project Home","See current workflow, progress, next step, research-production readiness, and quality gates."),("help-onboarding.html","Workflow & Help","Compare use cases, safeguards, outputs, navigation, and offline support.")]),
        ("Discover and govern the corpus", [("source-manager.html","Source Manager","Literature, reports, drafts, rights, permissions, and connector health."),("search-studio.html","Search Studio","Structured, semantic, citation, and branch-based discovery."),("ingestion-reconciliation.html","Ingestion Review","Canonicalization, duplicates, versions, corrections, retractions, and rights."),("corpus-canvas.html","Corpus Canvas","Clusters, discovery paths, coverage, and boundary sensitivity."),("screening.html","Screening","Human inclusion authority, active-learning order, audits, and stopping.")]),
        ("Read, interpret, and structure evidence", [("document-reader.html","Document Reader","Secure source inspection, parsed structure, and evidence spans."),("parsing-quality.html","Parsing Quality","Correct structures, anchors, tables, figures, and references."),("research-notebook.html","Research Notebook","Human memos, evolving questions, alternative readings, and lineage."),("evidence-matrix.html","Evidence Matrix","Extraction, verification, comparison, and adjudication."),("schema-manager.html","Schema Manager","Versioned fields, relations, packs, constraints, and impact.")]),
        ("Model the field and identify opportunities", [("claim-graph.html","Claim Graph","Claims, evidence, support, contradiction, qualification, and disputes."),("theory-map.html","Theory Map","Definitions, mechanisms, operationalizations, drift, and integration."),("critical-lens.html","Critical Lens","Assumptions, stakeholders, authority, dependency, and alternatives."),("opportunity-radar.html","Opportunity Radar","Plural opportunity types and multi-objective comparison."),("novelty-audit.html","Novelty Audit","Nearest prior work, challenge, and bounded disposition."),("synthesis-studio.html","Synthesis Studio","Cited syntheses, disagreement preservation, disclosure, and exports.")]),
        ("Design studies and produce manuscripts", [("study-design.html","Study Design Studio","Evidence-grounded empirical design alternatives, protocol, validity, ethics, and analysis."),("manuscript-blueprint.html","Manuscript Blueprint","Venue- and research-type-aware article skeleton, claim plan, and exhibit plan."),("technical-reports.html","Technical Reports & Results","Private report upload, result verification, deviation tracking, tables, and figures."),("manuscript-studio.html","Manuscript Studio","Source-grounded empirical, theory, and critical article drafting."),("reviewer-simulation.html","Reviewer Simulation","Independent multi-role critique and editorial synthesis."),("revision-response.html","Revision & Response","Issue triage, author dispositions, revisions, responses, and re-review."),("living-monitor.html","Living Monitor","New evidence, impacts, staleness, and recalculation.")]),
        ("Operations and trust", [("task-center.html","Task Center","Durable analysis and production workflows, progress, failures, resources, and human gates."),("audit-lineage.html","Audit & Lineage","Trace outputs to literature, reports, results, models, drafts, reviews, rights, and decisions."),("model-center.html","Model & Privacy","Model routing, egress, budgets, evaluation, and offline policy."),("project-settings.html","Project Settings","Storage, protection, privacy, backup, accessibility, app lock, and cross-platform portability.")]),
    ]
    sections=[]
    for heading,pages in groups:
        cards=''.join([f'<a class="card card-lg hoverable" href="{href}"><div class="card-header"><h3 class="card-title">{label}</h3>{icon("arrow-right")}</div><p class="small muted">{desc}</p></a>' for href,label,desc in pages])
        sections.append(f'<section class="section"><div class="section-header"><h2 class="section-title">{heading}</h2></div><div class="grid grid-3">{cards}</div></section>')
    content=dedent(f"""
      <div class="notice"><span>{icon('info')}</span><div><div class="notice-title">Approved, linked, workflow-oriented experience reference</div><div class="notice-text">The primary navigation adapts to the project use case and visually orders the appropriate workspaces. All tools remain available through a secondary inventory. Page routes, workflow contracts, required regions, tokens, and accessibility behavior are normative; mock values are illustrative.</div></div></div>
      {''.join(sections)}
      <section class="card card-lg section"><div class="card-header"><div><h2 class="card-title">Profile-specific operational consoles remain deferred</h2><div class="card-subtitle">Desktop research workflows are shared across supported operating systems; institutional and cloud administration require separately activated delivery profiles.</div></div>{badge('W10 / W11')}</div><p class="small muted">University deployment administration, tenant administration, billing, and managed-cloud operations consoles remain outside this reference. They require active hosted-profile requirements, their own approved page contracts, and the applicable architecture gate.</p></section>
    """)
    return shell("prototype-index", "Prototype Page Index", "Review the guided use cases, capability-complete researcher pages, research-production workspaces, and shared visual system.", content, actions, "Approved UI reference")

def style_guide_markdown() -> str:
    return (ROOT / "STYLE_GUIDE_SOURCE.md").read_text(encoding="utf-8")

def readme_markdown() -> str:
    return "# Research Observatory UI Reference\n\nThis directory is the approved, linked, offline experience reference for the PC/lab-first Research Observatory researcher application using **Academic Minimal 1.3**.\n\n## Start with the workflow\n\nOpen `new-project.html` to see use-case selection, `index.html` for the current project workflow, or `prototype-index.html` for every reference page. The sidebar's primary use-case selector changes the ordered guided navigation. The full tool inventory remains available under **All tools**.\n\n## Authority\n\n- `assets/tokens.css`, semantic rules in `STYLE_GUIDE.md`, the fourteen profiles in `WORKFLOW_CATALOG.*`, route inventory, required page regions, accessibility behavior, and approved visual baselines are normative.\n- Mock names, values, studies, providers, dates, prose, charts, and inactive actions are illustrative and do not create backend scope.\n- `APPROVAL.yaml` records approval; `REFERENCE_MANIFEST.yaml` identifies governed files; `CAPABILITY_COVERAGE.*` maps capabilities to pages.\n- Intentional user-facing changes require an updated proposed reference, validation, human approval, and only then application implementation.\n\n## Open locally\n\n```bash\npython -m http.server 8080\n```\n\nThen open `http://localhost:8080/prototype-index.html`.\n\n## Shared implementation\n\n- `assets/tokens.css` — canonical light/dark tokens.\n- `assets/app.css` — shared shell, workflow navigation, components, layouts, data displays, and responsive behavior.\n- `assets/app.js` — theme, sidebar, tabs, mock actions, use-case selection, adaptive workflow ordering, and context guidance.\n- `STYLE_GUIDE.md` / `style-guide.html` — technical and visual specification.\n- `WORKFLOW_CATALOG.md` / `.json` — authoritative use-case sequences and outputs.\n- `CAPABILITY_COVERAGE.md` / `.json` — page contracts and capability mapping.\n- `scripts/build_mockups.py` — deterministic page generator.\n- `scripts/verify_site.py` — reference integrity checks.\n\nUniversity/cloud administrator consoles remain intentionally deferred and require active W10/W11 requirements and separately approved page contracts.\n"

def inventory_markdown() -> str:
    return (ROOT / "PAGE_INVENTORY_SOURCE.md").read_text(encoding="utf-8")

def main() -> None:
    pages = {
        "index.html": page_home(),
        "projects.html": page_projects(),
        "new-project.html": page_new_project(),
        "intent-contract.html": page_intent_contract(),
        "search-studio.html": page_search_studio(),
        "source-manager.html": page_source_manager(),
        "ingestion-reconciliation.html": page_ingestion_reconciliation(),
        "corpus-canvas.html": page_corpus_canvas(),
        "screening.html": page_screening(),
        "document-reader.html": page_document_reader(),
        "research-notebook.html": page_research_notebook(),
        "parsing-quality.html": page_parsing_quality(),
        "evidence-matrix.html": page_evidence_matrix(),
        "schema-manager.html": page_schema_manager(),
        "claim-graph.html": page_claim_graph(),
        "theory-map.html": page_theory_map(),
        "critical-lens.html": page_critical_lens(),
        "opportunity-radar.html": page_opportunity_radar(),
        "novelty-audit.html": page_novelty_audit(),
        "synthesis-studio.html": page_synthesis_studio(),
        "study-design.html": page_study_design(),
        "manuscript-blueprint.html": page_manuscript_blueprint(),
        "technical-reports.html": page_technical_reports(),
        "manuscript-studio.html": page_manuscript_studio(),
        "reviewer-simulation.html": page_reviewer_simulation(),
        "revision-response.html": page_revision_response(),
        "living-monitor.html": page_living_monitor(),
        "task-center.html": page_task_center(),
        "audit-lineage.html": page_audit_lineage(),
        "model-center.html": page_model_center(),
        "project-settings.html": page_project_settings(),
        "help-onboarding.html": page_help_onboarding(),
        "style-guide.html": page_style_guide(),
        "prototype-index.html": page_prototype_index(),
    }
    for name, html in pages.items():
        write(name, html)
    (ROOT / "STYLE_GUIDE.md").write_text(style_guide_markdown(), encoding="utf-8")
    (ROOT / "README.md").write_text(readme_markdown(), encoding="utf-8")
    (ROOT / "PAGE_INVENTORY.md").write_text(inventory_markdown(), encoding="utf-8")
    print(f"Generated {len(pages)} HTML files in {ROOT}")


if __name__ == "__main__":
    main()
